package org.example.spotifymixer.runtime;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.function.Consumer;import java.io.IOException;
public class MixSessionTest {
    static String id(int i){return String.format(Locale.ROOT,"%022d",i);}
    static MixConfig config(boolean shuffle,int... ids){List<MixConfig.Source> sources=new ArrayList<>();for(int i=0;i<ids.length;i++)sources.add(new MixConfig.Source("spotify:playlist:"+id(ids[i]),"Source "+ids[i],i==ids.length-1?100-(100/ids.length)*i:100/ids.length));return new MixConfig(sources,shuffle);}
    static final class Backend implements MixSession.Backend {List<String> played;boolean fail,shuffled;Runnable loading;public MixSession.Playlist load(String uri,Consumer<String> progress)throws Exception{progress.accept("page");if(loading!=null)loading.run();if(fail)throw new IOException("offline");List<String> tracks=new ArrayList<>();int offset=Integer.parseInt(uri.substring(uri.length()-2))*200;for(int i=0;i<150;i++)tracks.add("spotify:track:"+id(i+offset));return new MixSession.Playlist(uri,tracks);}public void play(List<String> tracks,boolean shuffle){played=tracks;shuffled=shuffle;}}
    @Test public void loadsThreeFullSourcesAndOnlyPlaysOnExplicitStart()throws Exception{Backend b=new Backend();MixSession s=new MixSession(b);MixSession.Prepared p=s.prepare(config(false,1,2,3),m->{});assertNull(b.played);assertEquals(450,p.plan.tracks.size());assertEquals(Arrays.asList(150,150,150),p.plan.counts);s.start(p);assertEquals(450,b.played.size());try{s.start(p);fail();}catch(IOException expected){}}
    @Test public void failedReloadInvalidatesOldQueue()throws Exception{Backend b=new Backend();MixSession s=new MixSession(b);MixSession.Prepared p=s.prepare(config(false,1,2),m->{});b.fail=true;try{s.prepare(config(false,1,2),m->{});fail();}catch(IOException expected){}try{s.start(p);fail();}catch(IOException expected){}assertNull(b.played);}
    @Test public void replacementUsesNewSourcesAndShuffleSnapshot()throws Exception{Backend b=new Backend();MixSession s=new MixSession(b);MixSession.Prepared old=s.prepare(config(false,1,2),m->{});MixSession.Prepared next=s.prepare(config(true,3,4,5),m->{});try{s.start(old);fail();}catch(IOException expected){}assertEquals(3,next.config.sources.size());assertTrue(next.config.shuffle);s.start(next);assertTrue(b.shuffled);assertEquals(next.plan.tracks,b.played);}
    @Test public void cancellationCannotPublishPreparedQueue()throws Exception{Backend b=new Backend();MixSession s=new MixSession(b);b.loading=s::invalidate;try{s.prepare(config(false,1,2),m->{});fail();}catch(IOException|java.util.concurrent.CancellationException expected){}assertNull(b.played);}
}
